const body = $json.body ?? $json;
const dealId = body.dealId ?? body.deal_id;
const address = String(body.address ?? '').trim();
const city = String(body.city ?? '').trim();
let state = String(body.state ?? '').trim().toUpperCase();
const zip = String(body.zip ?? '').trim();
const county = String(body.county ?? '').trim();
if (!dealId || !address || !city || !state) {
  return [{json:{valid:false,error:'dealId, address, city, and state are required'}}];
}
const stateAliases = {
  'ALABAMA':'AL','ALASKA':'AK','ARIZONA':'AZ','ARKANSAS':'AR','CALIFORNIA':'CA','COLORADO':'CO',
  'CONNECTICUT':'CT','DELAWARE':'DE','FLORIDA':'FL','GEORGIA':'GA','HAWAII':'HI','IDAHO':'ID',
  'ILLINOIS':'IL','INDIANA':'IN','IOWA':'IA','KANSAS':'KS','KENTUCKY':'KY','LOUISIANA':'LA',
  'MAINE':'ME','MARYLAND':'MD','MASSACHUSETTS':'MA','MICHIGAN':'MI','MINNESOTA':'MN','MISSISSIPPI':'MS',
  'MISSOURI':'MO','MONTANA':'MT','NEBRASKA':'NE','NEVADA':'NV','NEW HAMPSHIRE':'NH','NEW JERSEY':'NJ',
  'NEW MEXICO':'NM','NEW YORK':'NY','NORTH CAROLINA':'NC','NORTH DAKOTA':'ND','OHIO':'OH','OKLAHOMA':'OK',
  'OREGON':'OR','PENNSYLVANIA':'PA','RHODE ISLAND':'RI','SOUTH CAROLINA':'SC','SOUTH DAKOTA':'SD',
  'TENNESSEE':'TN','TEXAS':'TX','UTAH':'UT','VERMONT':'VT','VIRGINIA':'VA','WASHINGTON':'WA',
  'WEST VIRGINIA':'WV','WISCONSIN':'WI','WYOMING':'WY','DISTRICT OF COLUMBIA':'DC'
};
state = stateAliases[state] || state;
if (!/^[A-Z]{2}$/.test(state)) {
  return [{json:{valid:false,error:'State must be a two-letter US postal abbreviation or full state name'}}];
}
const fullAddress = [address,city,state,zip].filter(Boolean).join(', ');
return [{json:{valid:true,dealId,address,city,state,zip,county,fullAddress,requestedAt:new Date().toISOString(),county_resolution_needed:!county}}];

const registry = {
  NC: {
    Catawba: [
      {id:'catawba_gis',type:'parcel_gis',evidenceType:'property_record',url:'https://gis.catawbacountync.gov/parcel/'},
      {id:'catawba_tax_real_estate',type:'tax_search',evidenceType:'tax_record',url:'https://taxbill.catawbacountync.gov/ITSPublicCT/RealEstateSearch'},
      {id:'catawba_tax_delinquent',type:'delinquent_tax_search',evidenceType:'tax_delinquency',url:'https://taxbill.catawbacountync.gov/ITSPublicCT/'},
      {id:'catawba_permits',type:'permit_search',evidenceType:'permit_record',url:'https://epermits.catawbacountync.gov/'},
      {id:'catawba_gis_datasets',type:'open_data',evidenceType:'county_dataset',url:'https://catawbacountync.gov/online-services/datasets/'},
      {id:'catawba_register_of_deeds',type:'land_records',evidenceType:'land_record',url:'https://catawbacountync.gov/county-services/register-of-deeds/'}
    ],
    Caldwell: [
      {id:'caldwell_gis',type:'parcel_gis',evidenceType:'property_record',url:'https://gis.caldwellcountync.org/'}
    ],
    Mecklenburg: [
      {id:'mecklenburg_gis',type:'parcel_gis',evidenceType:'property_record',url:'https://gis.mecknc.gov/'},
      {id:'mecklenburg_tax',type:'tax_search',evidenceType:'tax_record',url:'https://tax.mecknc.gov/'}
    ],
    Wake: [
      {id:'wake_real_estate',type:'real_estate_search',evidenceType:'property_record',url:'https://services.wake.gov/realestate/'},
      {id:'wake_tax_data',type:'property_data_files',evidenceType:'county_dataset',url:'https://www.wake.gov/departments-government/tax-administration/data-files-statistics-and-reports/real-estate-property-data-files'}
    ],
    'New Hanover': [
      {id:'new_hanover_gis',type:'parcel_gis',evidenceType:'property_record',url:'https://registerofdeeds.nhcgov.com/844/GIS-Maps-Data'},
      {id:'new_hanover_land_records',type:'land_records',evidenceType:'land_record',url:'https://strategy.nhcgov.com/376/Land-Records'},
      {id:'new_hanover_data',type:'open_data',evidenceType:'county_dataset',url:'https://www.nhcgov.com/1169/Find-Download-Data'}
    ]
  }
};
const state = String($json.state || '').trim().toUpperCase();
const county = String($json.county || '').trim();
const known = registry[state]?.[county] || [];
return [{json:{...$json,source_mode:known.length ? 'registry' : 'discovery',sources:known.map(s=>({...s,query:encodeURIComponent($json.fullAddress)})),source_discovery_query:known.length ? null : `Find the official county government/public-record sources for ${county} County, ${state} for this property address: ${$json.fullAddress}. Return only official government domains and categorize sources as parcel/GIS, assessment/tax, delinquent tax, permits, land records, and public datasets when available.`}}];

const src = $('Split Source Targets').item.json.source;
const base = $('Split Source Targets').item.json;
const raw = $json.data ?? $json;
const markdown = typeof raw === 'string' ? raw : (raw.markdown ?? raw.content ?? JSON.stringify(raw));
return [{json:{
  dealId:base.dealId,
  extraction_context:{
    address:base.fullAddress,
    state:base.state,
    county:base.county,
    source_id:src.id,
    source_type:src.type,
    source_url:src.url
  },
  evidence:{
    evidence_type:src.evidenceType,
    source:src.id,
    source_record_id:src.id + ':' + base.dealId,
    observed_at:new Date().toISOString(),
    confidence:0.65,
    payload:{
      address:base.fullAddress,
      county:base.county,
      source_url:src.url,
      source_type:src.type,
      collected_at:new Date().toISOString(),
      content:markdown
    }
  }
}}];

const base = $('Build State/County Source Targets').item.json;
const known = base.sources || [];
if (known.length) return [{json:{...base, sources:known}}];
const raw = $json;
let text = raw.output_text ?? raw.choices?.[0]?.message?.content ?? raw.data?.choices?.[0]?.message?.content ?? '';
if (typeof text !== 'string') text = JSON.stringify(text);
text = text.replace(/^\`\`\`json\s*/,'').replace(/\s*\`\`\`$/,'');
let discovered = [];
try { discovered = JSON.parse(text).sources || []; } catch {}
return [{json:{...base, sources:discovered.filter(s => s && s.url).map(s => ({...s, query:encodeURIComponent(base.fullAddress)}))}}];

const base=$('Prepare Property Request').item.json;
let text=$json.output_text ?? $json.choices?.[0]?.message?.content ?? $json.data?.choices?.[0]?.message?.content ?? '';
if(typeof text!=='string') text=JSON.stringify(text);
text=text.replace(/^\`\`\`json\s*/,'').replace(/\s*\`\`\`$/,'');
let county='', confidence=0, citations=[];
try { const parsed=JSON.parse(text); county=String(parsed.county||'').trim(); confidence=Number(parsed.confidence||0); citations=parsed.source_citations||[]; } catch {}
if(!county) return [{json:{...base,valid:false,error:'Unable to resolve county from the supplied address',county_resolution_confidence:confidence}}];
return [{json:{...base,county,county_resolution_confidence:confidence,county_resolution_sources:citations,county_resolution_needed:false}}];

const base=$('Normalize Evidence').item.json;
let text=$json.output_text ?? $json.choices?.[0]?.message?.content ?? $json.data?.output_text ?? '';
if(typeof text!=='string') text=JSON.stringify(text);
text=text.replace(/^\`\`\`json\s*/,'').replace(/\s*\`\`\`$/,'');
let facts={};
try { facts=JSON.parse(text); } catch {}
const evidence={...base.evidence,payload:{...base.evidence.payload,structured_facts:facts,extraction_method:'evidence_constrained_llm',extraction_model:$env.OPENAI_PROPERTY_EXTRACTION_MODEL || $env.OPENAI_DEAL_ANALYSIS_MODEL || 'gpt-5-mini'}};
return [{json:{dealId:base.dealId,evidence}}];

const items=$input.all(); if(!items.length) return [];
const first=items[0].json;
const evidence=items.map(i=>i.json.evidence).filter(Boolean);
return [{json:{
  dealId:first.dealId,
  evidence,
  analysisContext:{
    property_request:{
      address:first.evidence?.payload?.address || null,
      county:first.evidence?.payload?.county || null
    },
    evidence_count:evidence.length
  }
}}}];
